import fs from "node:fs/promises";
import crypto from "node:crypto";
import path from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = path.dirname(fileURLToPath(import.meta.url));
const outputRoot = path.join(projectRoot, "tilda");
const sourcePaths = {
  html: path.join(projectRoot, "index.html"),
  css: path.join(projectRoot, "styles.css"),
  js: path.join(projectRoot, "script.js"),
};
const assetIds = new Map([
  ["date-spark.svg", "anti-crisis-date-spark"],
  ["practice-benefit-icon.svg", "anti-crisis-benefit-star"],
  ["practice-connector.svg", "anti-crisis-practice-connector"],
  ["registration-shape.svg", "anti-crisis-registration-shape"],
  ["speakers-arrow.svg", "anti-crisis-speakers-arrow"],
]);

const [html, css, js] = await Promise.all([
  fs.readFile(sourcePaths.html, "utf8"),
  fs.readFile(sourcePaths.css, "utf8"),
  fs.readFile(sourcePaths.js, "utf8"),
]);

const bodyMatch = html.match(/<body>([\s\S]*?)<\/body>/i);

if (!bodyMatch) {
  throw new Error("The source document body could not be extracted.");
}

const usedAssets = new Set();
let body = bodyMatch[1].trim();

body = body.replace(
  /<img\b([^>]*?)\bsrc="assets\/([^"/]+\.svg)"([^>]*)>/gi,
  (match, beforeSource, filename, afterSource) => {
    const symbolId = assetIds.get(filename);

    if (!symbolId) {
      throw new Error(`No inline SVG symbol is configured for ${filename}.`);
    }

    usedAssets.add(filename);

    const attributes = `${beforeSource}${afterSource}`
      .replace(/\s+(?:alt|aria-hidden|draggable)="[^"]*"/gi, "")
      .trim();
    const attributePrefix = attributes ? ` ${attributes}` : "";

    return `<svg${attributePrefix} aria-hidden="true" focusable="false"><use href="#${symbolId}"></use></svg>`;
  },
);

const missingAssets = [...assetIds.keys()].filter(
  (filename) => !usedAssets.has(filename),
);

if (missingAssets.length) {
  throw new Error(`Configured SVG assets are unused: ${missingAssets.join(", ")}.`);
}

const symbols = await Promise.all(
  [...assetIds.entries()].map(async ([filename, symbolId]) => {
    const svg = await fs.readFile(
      path.join(projectRoot, "assets", filename),
      "utf8",
    );
    const svgMatch = svg.match(/<svg\b([^>]*)>([\s\S]*?)<\/svg>/i);

    if (!svgMatch) {
      throw new Error(`Invalid SVG asset: ${filename}.`);
    }

    const viewBox = svgMatch[1].match(/\bviewBox="([^"]+)"/i)?.[1];
    const preserveAspectRatio = svgMatch[1].match(
      /\bpreserveAspectRatio="([^"]+)"/i,
    )?.[1];
    const fill = svgMatch[1].match(/\bfill="([^"]+)"/i)?.[1];

    if (!viewBox) {
      throw new Error(`SVG asset has no viewBox: ${filename}.`);
    }

    const symbolAttributes = [
      `id="${symbolId}"`,
      `viewBox="${viewBox}"`,
      preserveAspectRatio
        ? `preserveAspectRatio="${preserveAspectRatio}"`
        : "",
      fill ? `fill="${fill}"` : "",
    ]
      .filter(Boolean)
      .join(" ");
    const symbolContent = svgMatch[2].replace(/\s+id="[^"]*"/gi, "");

    return `<symbol ${symbolAttributes}>${symbolContent}</symbol>`;
  }),
);

const sprite = [
  '<svg class="anti-crisis-svg-sprite" aria-hidden="true" focusable="false" width="0" height="0" style="position:absolute;width:0;height:0;overflow:hidden">',
  "<defs>",
  ...symbols,
  "</defs>",
  "</svg>",
].join("\n");

body = `${sprite}\n${body}`;
body = body.replace(/[ \t]+$/gm, "");

const head = `<!-- Anti-crisis conference: paste into Tilda page HEAD -->
<script>document.documentElement.classList.add("has-js");</script>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Wix+Madefor+Text:wght@400;500;600;700&amp;display=swap" rel="stylesheet">
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@splidejs/splide@4.1.4/dist/css/splide-core.min.css">
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/intl-tel-input@29.1.2/dist/css/intlTelInput.css">
<style>
${css.trim()}
</style>`;

const footer = `<!-- Anti-crisis conference: paste into the final T123 block below T706 -->
<script src="https://cdn.jsdelivr.net/npm/@splidejs/splide@4.1.4/dist/js/splide.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/intl-tel-input@29.1.2/dist/js/intlTelInput.min.js"></script>
<script>
${js.trim()}
</script>`;

const readme = `# Tilda transfer package

Generated by \`node build-tilda-bundle.mjs\`. Do not edit generated fragments;
edit the source HTML, CSS, or JavaScript and rebuild instead.

1. In the existing page-specific HEAD, preserve analytics but remove the old
   manually inserted JSON-LD; Tilda's native settings own structured data.
   Remove the stray closing \`</script>\` and the second, duplicate BotHelp
   loader, then append \`head.html\`. Keep exactly one site-wide BotHelp loader.
2. Add one T123 block for \`body.html\`.
3. Keep the native ST100/T706 cart on the same page with required Name, Email,
   and Phone fields plus the approved Tinkoff and Dolyame payment methods.
4. Add another T123 block as the last page block, below T706, and paste
   \`footer.html\` into it. The vendor scripts intentionally load before the
   project script.
5. Set the SEO title, description, canonical, Open Graph text, and social image
   in Tilda settings as documented in the project README.
6. Publish the page before testing because T123 code does not run in the editor.

## Smoke test after publishing

- Free mode: personal fields stay hidden and disabled; the CTA opens BotHelp;
  close it by button, overlay, and Escape, and verify keyboard focus returns.
- Paid RU: enter name, email, and a valid Russian number, then open the cart.
  Verify exactly one 1 999 RUB product, matching name/email, and one +7 prefix.
- Reopen the paid cart: quantity must remain one; no duplicate product is added.
- Paid international: test Belarus or Uzbekistan. The cart must retain the full
  +375 or +998 E.164 number. Kazakhstan shares +7, so verify all national digits.
- Invalid or incomplete phone values must remain on the local form with an
  inline error. Tinkoff and Dolyame must remain selectable in the native cart.
- Check widths 375, 768, 1024, and 1440 px, keyboard navigation, the country
  search field, console errors, failed requests, and horizontal overflow.
- Stop before entering or charging a real card.

The generated BODY contains one inline SVG sprite. It has no relative local
asset references and can be copied without uploading the repository's SVG files.
`;

const generatedFiles = {
  "head.html": `${head}\n`,
  "body.html": `${body}\n`,
  "footer.html": `${footer}\n`,
  "README.md": readme,
};

generatedFiles["manifest.json"] = `${JSON.stringify(
  {
    files: Object.fromEntries(
      Object.entries(generatedFiles).map(([filename, content]) => [
        filename,
        {
          bytes: Buffer.byteLength(content),
          sha256: crypto.createHash("sha256").update(content).digest("hex"),
        },
      ]),
    ),
  },
  null,
  2,
)}\n`;

for (const [filename, content] of Object.entries(generatedFiles)) {
  if (/\b(?:src|href)="(?:assets\/|styles\.css|script\.js)/i.test(content)) {
    throw new Error(`${filename} still contains a local runtime dependency.`);
  }
}

if ((body.match(/data-page="anti-crisis-conference"/g) || []).length !== 1) {
  throw new Error("The generated body must contain exactly one page root.");
}

if ((body.match(/id="bh-widget-button-root"/g) || []).length !== 1) {
  throw new Error("The generated body must contain exactly one BotHelp root.");
}

await fs.mkdir(outputRoot, { recursive: true });
await Promise.all(
  Object.entries(generatedFiles).map(([filename, content]) =>
    fs.writeFile(path.join(outputRoot, filename), content, "utf8"),
  ),
);

console.log(
  `Tilda bundle generated: ${Object.keys(generatedFiles).join(", ")}`,
);
